class P { n: number; tag: string; constructor(n: number, tag: string = "t") { this.n = n; this.tag = tag; } get twice(): number { return this.n * 2; } }
function main(): void {
  const k: any = P; const o = new k(21, "z");
  console.log(o.n, o.tag, o.twice);
  const d = new k(1); console.log(d.tag);
}
